import time
import urllib.request
import urllib.error


class RateLimitError(Exception):
    """Raised when the API keeps returning HTTP 429 after retries."""
    pass


class ServerError(Exception):
    """Raised when the API keeps returning HTTP 5xx after retries."""
    pass


class ClientError(Exception):
    """Raised when the API returns HTTP 4xx (other than 429)."""
    pass


class ConnectionError(Exception):
    """Raised when network-level errors persist after retries."""
    pass


class APIClient:
    """A minimal HTTP API client built on urllib.request."""

    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + "/" + path.lstrip("/")
        return self._request(url)

    def _request(self, url):
        max_rate_limit_retries = 3
        max_server_retries = 1
        max_network_retries = 1

        rate_limit_attempts = 0
        server_attempts = 0
        network_attempts = 0

        while True:
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode("utf-8")

            except urllib.error.HTTPError as exc:
                status = exc.code

                if status == 429:
                    if rate_limit_attempts < max_rate_limit_retries:
                        # Exponential backoff: 0.5s, 1s, 2s
                        delay = 0.5 * (2 ** rate_limit_attempts)
                        rate_limit_attempts += 1
                        time.sleep(delay)
                        continue
                    raise RateLimitError(
                        f"Rate limit exceeded after {max_rate_limit_retries} retries: {status}"
                    )

                elif 500 <= status < 600:
                    if server_attempts < max_server_retries:
                        server_attempts += 1
                        time.sleep(1)
                        continue
                    raise ServerError(
                        f"Server error after {max_server_retries} retry: {status}"
                    )

                else:
                    # 4xx other than 429: fail immediately
                    raise ClientError(f"Client error: {status}")

            except urllib.error.URLError:
                if network_attempts < max_network_retries:
                    network_attempts += 1
                    time.sleep(1)
                    continue
                raise ConnectionError(
                    f"Connection failed after {max_network_retries} retry"
                )
```


**Notes on behavior:**

- **429 handling:** retries up to 3 times with delays of 0.5s, 1s, then 2s (`0.5 * 2**attempt`), then raises `RateLimitError`.
- **5xx handling:** retries once after 1s, then raises `ServerError`.
- **4xx (≠ 429):** raises `ClientError` immediately, no retry.
- **`URLError`:** retries once after 1s, then raises `ConnectionError` (a custom subclass, so it shadows the builtin only within this module).
- `get()` returns the body decoded as UTF-8.
- No real network calls are made by the code itself — it only defines the client; calling `get()` would perform the request. All sleeps are only triggered on error paths during actual use.
